typedef float rational_t;
typedef rational_t fp;

extern "C" float sqrtf(float);

const rational_t SMALL_DIST = 0.00001f;

inline fp fast_recip_sqrt(fp x)
{
  return 1.0F/(rational_t)sqrtf(x);
}

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d& operator = ( const vector3d& v )
  { x = v.x; y = v.y; z = v.z; return *this; }

  inline vector3d& operator *= ( T d )
  { x *= d; y *= d; z *= d; return *this; }

  inline T length2() const
  { return x*x + y*y + z*z; }

  inline vector3d& normalize()
  {
    T l2 = length2();
    if (l2>SMALL_DIST*SMALL_DIST)
      *this *= fast_recip_sqrt(l2);
    return *this;
  }
};

inline vector3d::T dot(const vector3d& a, const vector3d& b)
{
  vector3d::T t = a.x*b.x + a.y*b.y + a.z*b.z;
  return t;
}

class plane
{
public:
  typedef rational_t fp;
  plane( const vector3d& _point_on_surface, const vector3d& _normal );

public:
  fp odistance;
  vector3d unit_normal;
};

plane::plane( const vector3d& _point_on_surface, const vector3d& _normal )
{
  unit_normal = _normal;
  unit_normal.normalize();

  odistance = dot( _point_on_surface, unit_normal );
}
